import{_ as t,o as e,c as d,Q as r}from"./chunks/framework.48927342.js";const x=JSON.parse('{"title":"Numbers and Numeral Grammar","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/grammar/05-numbers.md","filePath":"en/more/maltese/grammar/05-numbers.md"}'),a={name:"en/more/maltese/grammar/05-numbers.md"},n=r('<h1 id="numbers-and-numeral-grammar" tabindex="-1">Numbers and Numeral Grammar <a class="header-anchor" href="#numbers-and-numeral-grammar" aria-label="Permalink to &quot;Numbers and Numeral Grammar&quot;">​</a></h1><h2 id="_1-numbers-from-0-to-20" tabindex="-1">1. Numbers from 0 to 20 <a class="header-anchor" href="#_1-numbers-from-0-to-20" aria-label="Permalink to &quot;1. Numbers from 0 to 20&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">Number</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>zero</td><td>żero</td></tr><tr><td style="text-align:right;">1</td><td>one</td><td>wieħed / waħda</td></tr><tr><td style="text-align:right;">2</td><td>two</td><td>tnejn</td></tr><tr><td style="text-align:right;">3</td><td>three</td><td>tlieta</td></tr><tr><td style="text-align:right;">4</td><td>four</td><td>erbgħa</td></tr><tr><td style="text-align:right;">5</td><td>five</td><td>ħamsa</td></tr><tr><td style="text-align:right;">6</td><td>six</td><td>sitta</td></tr><tr><td style="text-align:right;">7</td><td>seven</td><td>sebgħa</td></tr><tr><td style="text-align:right;">8</td><td>eight</td><td>tmienja</td></tr><tr><td style="text-align:right;">9</td><td>nine</td><td>disgħa</td></tr><tr><td style="text-align:right;">10</td><td>ten</td><td>għaxra</td></tr><tr><td style="text-align:right;">11</td><td>eleven</td><td>ħdax</td></tr><tr><td style="text-align:right;">12</td><td>twelve</td><td>tnax</td></tr><tr><td style="text-align:right;">13</td><td>thirteen</td><td>tlettax</td></tr><tr><td style="text-align:right;">14</td><td>fourteen</td><td>erbatax</td></tr><tr><td style="text-align:right;">15</td><td>fifteen</td><td>ħmistax</td></tr><tr><td style="text-align:right;">16</td><td>sixteen</td><td>sittax</td></tr><tr><td style="text-align:right;">17</td><td>seventeen</td><td>sbatax</td></tr><tr><td style="text-align:right;">18</td><td>eighteen</td><td>tmintax</td></tr><tr><td style="text-align:right;">19</td><td>nineteen</td><td>dsatax</td></tr><tr><td style="text-align:right;">20</td><td>twenty</td><td>għoxrin</td></tr></tbody></table><h2 id="_2-tens-and-larger-numbers" tabindex="-1">2. Tens and Larger Numbers <a class="header-anchor" href="#_2-tens-and-larger-numbers" aria-label="Permalink to &quot;2. Tens and Larger Numbers&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">Number</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">30</td><td>thirty</td><td>tletin</td></tr><tr><td style="text-align:right;">40</td><td>forty</td><td>erbgħin</td></tr><tr><td style="text-align:right;">50</td><td>fifty</td><td>ħamsin</td></tr><tr><td style="text-align:right;">60</td><td>sixty</td><td>sittin</td></tr><tr><td style="text-align:right;">70</td><td>seventy</td><td>sebgħin</td></tr><tr><td style="text-align:right;">80</td><td>eighty</td><td>tmenin</td></tr><tr><td style="text-align:right;">90</td><td>ninety</td><td>disgħin</td></tr><tr><td style="text-align:right;">100 (standalone)</td><td>one hundred (standalone)</td><td>mija</td></tr><tr><td style="text-align:right;">100 (before a noun)</td><td>one hundred (before a noun)</td><td>mitt</td></tr><tr><td style="text-align:right;">200</td><td>two hundred</td><td>mitejn</td></tr><tr><td style="text-align:right;">1,000</td><td>one thousand</td><td>elf</td></tr><tr><td style="text-align:right;">2,000</td><td>two thousand</td><td>elfejn</td></tr><tr><td style="text-align:right;">1,000,000</td><td>one million</td><td>miljun</td></tr></tbody></table><h2 id="_3-compound-numbers" tabindex="-1">3. Compound Numbers <a class="header-anchor" href="#_3-compound-numbers" aria-label="Permalink to &quot;3. Compound Numbers&quot;">​</a></h2><p>A common pattern for 21–99 is “unit + <code>u</code> + ten.” Here <code>u</code> means “and”: <code>ħamsa u għoxrin</code> (25). Hundreds and thousands have their own forms, so do not apply this pattern mechanically to every number.</p><ul><li>21: <code>wieħed u għoxrin</code></li><li>22: <code>tnejn u għoxrin</code></li><li>35: <code>ħamsa u tletin</code></li><li>48: <code>tmienja u erbgħin</code></li><li>99: <code>disgħa u disgħin</code></li></ul><p>Common forms for hundreds and thousands include <code>mija</code> (one hundred, when stated on its own), <code>mitt</code> (one hundred before a noun), <code>mitejn</code> (two hundred), <code>tliet mija</code> (three hundred), <code>elf</code> (one thousand), <code>elfejn</code> (two thousand), and <code>tlitt elef</code> (three thousand). Short and long numeral forms may occur in context; forms used for dates, time, and counting are not always interchangeable.</p><h2 id="_4-gender-and-numeral-forms" tabindex="-1">4. Gender and Numeral Forms <a class="header-anchor" href="#_4-gender-and-numeral-forms" aria-label="Permalink to &quot;4. Gender and Numeral Forms&quot;">​</a></h2><ul><li><code>wieħed</code> is commonly associated with masculine nouns and <code>waħda</code> with feminine nouns: <code>raġel wieħed</code> (one man), <code>dar waħda</code> (one house).</li><li>Numerals may contract or take special forms when used with nouns, such as <code>żewġt iklieb</code> (two dogs) and <code>żewġt itfal</code> (two children). Do not assume every numeral can simply be placed before a noun unchanged.</li><li>Forms for 2–10 follow historical patterns involving noun number and gender. Learn common combinations as phrases; the forms here are standalone numerals for beginners.</li></ul><blockquote><p><strong>Tip:</strong> <code>tlieta</code> is the standalone form for “three,” as in <code>Wieħed, tnejn, tlieta</code> (one, two, three). Before nouns, the modifying form is usually <code>tliet</code>: <code>tliet sigħat</code> (three hours), <code>tliet ġimgħat</code> (three weeks). <code>jiem</code> (days) is an exception: use <code>tlett ijiem</code> (three days). Do not use standalone <code>tlieta</code> directly before these nouns.</p></blockquote><h2 id="_5-ordinal-numbers" tabindex="-1">5. Ordinal Numbers <a class="header-anchor" href="#_5-ordinal-numbers" aria-label="Permalink to &quot;5. Ordinal Numbers&quot;">​</a></h2><p>Ordinal numbers express position (“which one in order”). Common forms usually take the definite article and precede the noun, as in <code>l-ewwel jum</code> (the first day) and <code>it-tieni darba</code> (the second time).</p><table><thead><tr><th style="text-align:right;">Number</th><th>English ordinal</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>first</td><td>l-ewwel</td></tr><tr><td style="text-align:right;">2</td><td>second</td><td>it-tieni</td></tr><tr><td style="text-align:right;">3</td><td>third</td><td>it-tielet</td></tr><tr><td style="text-align:right;">4</td><td>fourth</td><td>ir-raba&#39;</td></tr><tr><td style="text-align:right;">5</td><td>fifth</td><td>il-ħames</td></tr><tr><td style="text-align:right;">6</td><td>sixth</td><td>is-sitt</td></tr><tr><td style="text-align:right;">7</td><td>seventh</td><td>is-seba&#39;</td></tr><tr><td style="text-align:right;">8</td><td>eighth</td><td>it-tmien</td></tr><tr><td style="text-align:right;">9</td><td>ninth</td><td>id-disa&#39;</td></tr><tr><td style="text-align:right;">10</td><td>tenth</td><td>l-għaxar</td></tr><tr><td style="text-align:right;">11</td><td>eleventh</td><td>il-ħdax</td></tr><tr><td style="text-align:right;">12</td><td>twelfth</td><td>it-tnax</td></tr><tr><td style="text-align:right;">13</td><td>thirteenth</td><td>it-tlettax</td></tr><tr><td style="text-align:right;">14</td><td>fourteenth</td><td>l-erbatax</td></tr><tr><td style="text-align:right;">15</td><td>fifteenth</td><td>il-ħmistax</td></tr><tr><td style="text-align:right;">16</td><td>sixteenth</td><td>is-sittax</td></tr><tr><td style="text-align:right;">17</td><td>seventeenth</td><td>is-sbatax</td></tr><tr><td style="text-align:right;">18</td><td>eighteenth</td><td>it-tmintax</td></tr><tr><td style="text-align:right;">19</td><td>nineteenth</td><td>id-dsatax</td></tr><tr><td style="text-align:right;">20</td><td>twentieth</td><td>l-għoxrin</td></tr></tbody></table><p>These forms are a beginner reference. With a noun, the definite article is generally retained; learn the whole phrase together.</p><p>Fractions and decimals depend on the mathematical, monetary, or measurement context. When shopping, beginners can write the number or ask the other person to repeat it if unsure.</p><h2 id="_6-prices-and-quantities" tabindex="-1">6. Prices and Quantities <a class="header-anchor" href="#_6-prices-and-quantities" aria-label="Permalink to &quot;6. Prices and Quantities&quot;">​</a></h2><ul><li><code>Kemm jiswa dan?</code>: How much is this? (masculine noun)</li><li><code>Kemm tiswa din?</code>: How much is this? (feminine noun)</li><li><code>Żewġ kafejiet, jekk jogħġbok.</code>: Two coffees, please. (The plural of <code>kafè</code> varies by usage; this is a common expression.)</li><li><code>Għandi tliet kotba.</code>: I have three books.</li></ul><blockquote><p>Numeral-noun combinations are not entirely regular. Learn common combinations as units and check an unfamiliar plural in a dictionary.</p></blockquote><h2 id="_7-ten-examples-of-large-numbers" tabindex="-1">7. Ten Examples of Large Numbers <a class="header-anchor" href="#_7-ten-examples-of-large-numbers" aria-label="Permalink to &quot;7. Ten Examples of Large Numbers&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>twenty-five</td><td>ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">2</td><td>one hundred and twenty-five</td><td>mija u ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">3</td><td>two hundred and twenty-five</td><td>mitejn u ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">4</td><td>three hundred and twenty-five</td><td>tliet mija u ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">5</td><td>one thousand and twenty-five</td><td>elf u ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">6</td><td>one thousand one hundred and twenty-five</td><td>elf, mija u ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">7</td><td>two thousand one hundred and twenty-five</td><td>elfejn, mija u ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">8</td><td>three thousand</td><td>tlitt elef</td></tr><tr><td style="text-align:right;">9</td><td>ten thousand</td><td>għaxra elf</td></tr><tr><td style="text-align:right;">10</td><td>one hundred thousand</td><td>mija elf</td></tr></tbody></table><p>These examples use common counting forms. <code>mija</code> is used alone or in compound numbers; <code>mitt</code> is the form used before a noun.</p><h2 id="_8-references" tabindex="-1">8. References <a class="header-anchor" href="#_8-references" aria-label="Permalink to &quot;8. References&quot;">​</a></h2><ul><li><a href="https://www.omniglot.com/language/numbers/maltese.htm" target="_blank" rel="noreferrer">Omniglot: Maltese numbers</a></li><li><a href="https://en.wiktionary.org/wiki/mija#Maltese" target="_blank" rel="noreferrer">Wiktionary: mija</a></li><li><a href="https://en.wiktionary.org/wiki/ewwel#Maltese" target="_blank" rel="noreferrer">Wiktionary: ewwel</a></li></ul>',25),i=[n];function o(l,s,h,m,g,u){return e(),d("div",null,i)}const y=t(a,[["render",o]]);export{x as __pageData,y as default};
